# Homebrew formula for the SendSets CLI. Generated by scripts/build-cli.sh;
# the release workflow pushes it to the AddisonHoff/homebrew-tap repository.
class Sendsets < Formula
  desc "SendSets from the command line: campaigns, contacts, mailboxes, inbox"
  homepage "https://sendsetsapi.com"
  version "0.4.24"
  license "Apache-2.0"

  on_macos do
    on_intel do
      url "https://github.com/AddisonHoff/sendsets-releases/releases/download/v0.4.24/sendsets_darwin_amd64.tar.gz"
      sha256 "031296332dc2af6d18d528108d42831a4f1d53ab6ee4e0489c861586c9b1ca3f"
    end
    on_arm do
      url "https://github.com/AddisonHoff/sendsets-releases/releases/download/v0.4.24/sendsets_darwin_arm64.tar.gz"
      sha256 "42cc077bf661c2398ba71c986addec093ba9db3d57355148623a22425d36869c"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/AddisonHoff/sendsets-releases/releases/download/v0.4.24/sendsets_linux_amd64.tar.gz"
      sha256 "383bdecc1847fd90d62ef8629a58fb7584bd45afeabfbd12c61b14416f71ab3e"
    end
    on_arm do
      url "https://github.com/AddisonHoff/sendsets-releases/releases/download/v0.4.24/sendsets_linux_arm64.tar.gz"
      sha256 "0bebdc963e2f76427e3d715ec685a993ec97aeaa2bb59ebbe407defae36ccc6a"
    end
  end

  def install
    bin.install "sendsets"
    bash_completion.install "completions/sendsets.bash" => "sendsets"
    zsh_completion.install "completions/sendsets.zsh" => "_sendsets"
    fish_completion.install "completions/sendsets.fish" => "sendsets.fish"
  end

  test do
    assert_match "sendsets", shell_output("#{bin}/sendsets version")
  end
end
